{"command":"cat <<'EOF' > test_debug.cpp
#include "llvm/Analysis/ScalarEvolution.h"
#include "llvm/IR/LLVMContext.h"
#include "llvm/IR/Module.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Dominators.h"
#include "llvm/Analysis/LoopInfo.h"
#include "llvm/IRReader/IRReader.h"
#include "llvm/Support/SourceMgr.h"
#include "llvm/Support/raw_ostream.h"

using namespace llvm;

int main() {
  LLVMContext Context;
  SMDiagnostic Err;

  const char *IR = R"ir(
define i32 @test(i32 %x, i32 %y, i1 %cond) {
entry:
  br i1 %cond, label %left, label %right
left:
  %add1 = add i32 %x, 1
  br label %merge
right:
  %add2 = add i32 %y, 2
  br label %merge
merge:
  %result = phi i32 [ %add1, %left ], [ %add2, %right ]
  ret i32 %result
}
  )ir";

  std::unique_ptr<Module> M = parseIR(MemoryBufferRef(IR, "test"), Err, Context);
  if (!M) {
    errs() << "Failed to parse IR\n";
    return 1;
  }

  Function *F = M->getFunction("test");
  if (!F) {
    errs() << "Function not found\n";
    return 1;
  }

  DominatorTree DT(*F);
  LoopInfo LI(DT);
  TargetLibraryInfoImpl TLII;
  TargetLibraryInfo TLI(TLII);
  AssumptionCache AC(*F);
  ScalarEvolution SE(*F, TLI, AC, DT, LI);

  // Find the phi
  for (BasicBlock &BB : *F) {
    for (Instruction &I : BB) {
      if (PHINode *PN = dyn_cast<PHINode>(&I)) {
        errs() << "Found phi: " << *PN << "\n";
        const SCEV *S = SE.getSCEV(PN);
        errs() << "SCEV: " << *S << "\n";
      }
    }
  }

  return 0;
}
EOF"}

